def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse major.minor.patch
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            prerelease_identifiers = prerelease.split('.')

        return (major, minor, patch, prerelease_identifiers)

    def prerelease_key(identifiers):
        # A version with no pre-release sorts after one with pre-release
        # So we return a tuple where: (has_prerelease, identifiers_key)
        # has_prerelease=False (0) for version with prerelease, True (1) for version without
        if not identifiers:
            return (1,)  # No prerelease sorts after

        key = []
        for identifier in identifiers:
            if identifier.isdigit():
                # Numeric identifier: (0, numeric_value)
                key.append((0, int(identifier)))
            else:
                # Non-numeric identifier: (1, string_value)
                key.append((1, identifier))
        return (0, tuple(key))

    def version_key(parsed):
        major, minor, patch, prerelease_ids = parsed
        return (major, minor, patch, prerelease_key(prerelease_ids))

    # Create list of (index, version_string, parsed) tuples to maintain stable sort
    indexed_versions = [(i, v, parse_version(v)) for i, v in enumerate(versions)]

    # Sort by version key, then by original index for stability
    sorted_versions = sorted(indexed_versions, key=lambda x: (version_key(x[2]), x[0]))

    return [v for _, v, _ in sorted_versions]

